CREATE TABLE "apr_convite" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"os_id" uuid NOT NULL,
	"convidado_por_id" uuid NOT NULL,
	"usuario_id" uuid NOT NULL,
	"estado" text DEFAULT 'pendente' NOT NULL,
	"criado_em" timestamp with time zone NOT NULL,
	"expira_em" timestamp with time zone NOT NULL,
	"respondido_em" timestamp with time zone,
	"recusa_motivo" text,
	"apr_id" uuid,
	CONSTRAINT "apr_convite_estado_check" CHECK ("apr_convite"."estado" in ('pendente', 'aceito', 'recusado', 'cancelado', 'usado')),
	CONSTRAINT "apr_convite_nao_se_convida" CHECK ("apr_convite"."usuario_id" <> "apr_convite"."convidado_por_id"),
	CONSTRAINT "apr_convite_resposta_completa" CHECK (("apr_convite"."estado" in ('aceito', 'recusado', 'usado')) = ("apr_convite"."respondido_em" is not null) or "apr_convite"."estado" = 'cancelado'),
	CONSTRAINT "apr_convite_recusa_com_motivo" CHECK ("apr_convite"."estado" <> 'recusado' or nullif(btrim("apr_convite"."recusa_motivo"), '') is not null),
	CONSTRAINT "apr_convite_usado_com_apr" CHECK (("apr_convite"."estado" = 'usado') = ("apr_convite"."apr_id" is not null))
);
--> statement-breakpoint
ALTER TABLE "apr_convite" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "dispositivo_push" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"usuario_id" uuid NOT NULL,
	"token" text NOT NULL,
	"plataforma" text NOT NULL,
	"registrado_em" timestamp with time zone DEFAULT now() NOT NULL,
	"confirmado_em" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dispositivo_push_plataforma_check" CHECK ("dispositivo_push"."plataforma" in ('android', 'ios'))
);
